revoke insert,update,delete on company_integrations, ai_settings, whatsapp_contacts, usage_counters, integration_logs from authenticated;
drop policy if exists company_isolation on company_integrations; drop policy if exists company_isolation on ai_settings; drop policy if exists company_isolation on whatsapp_contacts; drop policy if exists company_isolation on usage_counters; drop policy if exists company_isolation on integration_logs;
create policy integration_admin_select on company_integrations for select using (current_company_role(company_id) in ('admin','gestor'));
create policy ai_settings_manage on ai_settings for all using (current_company_role(company_id) in ('admin','gestor')) with check (current_company_role(company_id) in ('admin','gestor'));
create policy whatsapp_contact_select on whatsapp_contacts for select using (is_company_member(company_id));
create policy usage_select on usage_counters for select using (is_company_member(company_id));
create policy integration_log_select on integration_logs for select using (current_company_role(company_id) in ('admin','gestor'));
create table if not exists integration_rate_limits(company_id uuid not null references companies(id) on delete cascade,user_id uuid,metric text not null,window_start timestamptz not null,count integer not null default 0,primary key(company_id,user_id,metric,window_start));
alter table integration_rate_limits enable row level security; revoke all on integration_rate_limits from authenticated;
create or replace function increment_usage(target_company uuid,target_metric text,target_period date,amount integer default 1) returns integer language plpgsql security definer set search_path=public as $$ declare n integer; begin insert into usage_counters(company_id,metric,period,count) values(target_company,target_metric,target_period,amount) on conflict(company_id,metric,period) do update set count=usage_counters.count+excluded.count returning count into n; return n; end; $$;
create or replace function consume_rate_limit(target_company uuid,target_user uuid,target_metric text,max_count integer,window_seconds integer default 60) returns boolean language plpgsql security definer set search_path=public as $$ declare w timestamptz:=to_timestamp(floor(extract(epoch from now())/window_seconds)*window_seconds); n integer; begin insert into integration_rate_limits(company_id,user_id,metric,window_start,count) values(target_company,target_user,target_metric,w,1) on conflict(company_id,user_id,metric,window_start) do update set count=integration_rate_limits.count+1 returning count into n; return n<=max_count; end; $$;
revoke all on function increment_usage(uuid,text,date,integer),consume_rate_limit(uuid,uuid,text,integer,integer) from public,anon; grant execute on function increment_usage(uuid,text,date,integer),consume_rate_limit(uuid,uuid,text,integer,integer) to authenticated;
